   120→// FindMostRecentSession returns the session ID of the most recently interacted session
   121→// (by LastInteractionTime), regardless of phase. Returns empty string if no sessions exist.
   122→// This replaces paths.ReadCurrentSession() for callers that need "the current session".
   123→func FindMostRecentSession() string {
   124→	states, err := ListSessionStates()
   125→	if err != nil || len(states) == 0 {
   126→		return ""
   127→	}
   128→
   129→	var best *SessionState
   130→	for _, s := range states {
   131→		if s.LastInteractionTime == nil {
   132→			continue
   133→		}
   134→		if best == nil || s.LastInteractionTime.After(*best.LastInteractionTime) {
   135→			best = s
   136→		}
   137→	}
   138→	if best != nil {
   139→		return best.SessionID
   140→	}
   141→
   142→	// Fallback: return most recently started session
   143→	for _, s := range states {
