   154→// TransitionAndLog runs a session phase transition, applies common actions, logs the
   155→// transition, and returns any remaining strategy-specific actions.
   156→// This is the single entry point for all state machine transitions to ensure
   157→// consistent logging of phase changes.
   158→func TransitionAndLog(state *SessionState, event session.Event, ctx session.TransitionContext) []session.Action {
   159→	oldPhase := state.Phase
   160→	result := session.Transition(oldPhase, event, ctx)
   161→	remaining := session.ApplyCommonActions(state, result)
   162→
   163→	logCtx := logging.WithComponent(context.Background(), "session")
   164→	if result.NewPhase != oldPhase {
   165→		logging.Info(logCtx, "phase transition",
   166→			slog.String("session_id", state.SessionID),
   167→			slog.String("event", event.String()),
   168→			slog.String("from", string(oldPhase)),
   169→			slog.String("to", string(result.NewPhase)),
   170→		)
   171→	} else {
   172→		logging.Debug(logCtx, "phase unchanged",
   173→			slog.String("session_id", state.SessionID),
   174→			slog.String("event", event.String()),
   175→			slog.String("phase", string(result.NewPhase)),
   176→		)
   177→	}
   178→
   179→	return remaining
   180→}
