   182→// ClearSessionState removes the session state file for the given session ID.
   183→func ClearSessionState(sessionID string) error {
   184→	// Validate session ID to prevent path traversal
   185→	if err := validation.ValidateSessionID(sessionID); err != nil {
   186→		return fmt.Errorf("invalid session ID: %w", err)
   187→	}
   188→
   189→	stateFile, err := sessionStateFile(sessionID)
   190→	if err != nil {
