   194→	if err := os.Remove(stateFile); err != nil {
   195→		if os.IsNotExist(err) {
   196→			return nil // Already gone, not an error
   197→		}
   198→		return fmt.Errorf("failed to remove session state file: %w", err)
   199→	}
   200→	return nil
   201→}
