// LogFileName is the fixed log file name used within the logs directory.
const LogFileName = "entire.log"

// Init initializes the logger, writing JSON logs to .entire/logs/entire.log.
// All sessions in the same worktree share a single log file; use SetSessionID
// to tag subsequent log lines with the active session.
//
// Safe to call multiple times — subsequent calls are no-ops if the file is
// already open. If the log file cannot be created, falls back to stderr.
// Log level is controlled by ENTIRE_LOG_LEVEL environment variable.
func Init() error {
	mu.Lock()
	defer mu.Unlock()

	// Already initialized — nothing to do.
	if logFile != nil {
		return nil
	}

	// Get log level from environment first, then settings
	levelStr := os.Getenv(LogLevelEnvVar)
	if levelStr == "" && logLevelGetter != nil {
		levelStr = logLevelGetter()
	}
	level := parseLogLevel(levelStr)

	// Warn if invalid level was provided
	if levelStr != "" && !isValidLogLevel(levelStr) {
		fmt.Fprintf(os.Stderr, "[entire] Warning: invalid log level %q, defaulting to INFO\n", levelStr)
	}

	// Determine log file path
	repoRoot, err := paths.RepoRoot()
	if err != nil {
		// Fall back to current directory
		repoRoot = "."
	}

	logsPath := filepath.Join(repoRoot, LogsDir)
	if err := os.MkdirAll(logsPath, 0o750); err != nil {
		// Fall back to stderr
		logger = createLogger(os.Stderr, level)
		return nil
	}

	logFilePath := filepath.Join(logsPath, LogFileName)
	f, err := os.OpenFile(logFilePath, os.O_CREATE|os.O_APPEND|os.O_WRONLY, 0o600)
	if err != nil {
		// Fall back to stderr
		logger = createLogger(os.Stderr, level)
		return nil
	}

	logFile = f
	logBufWriter = bufio.NewWriterSize(f, 8192) // 8KB buffer for batched writes
	logger = createLogger(logBufWriter, level)

	return nil
}

// SetSessionID updates the session ID that is included in every log line.
// Safe to call before or after Init. Typically called by agent hook handlers
// once they have parsed the actual session ID from stdin.
func SetSessionID(sessionID string) {
	mu.Lock()
	defer mu.Unlock()
	currentSessionID = sessionID
}

